mapper.select:
select goods.*, category.name as categoryName from goods left join category on goods.category_id = category.id
and goods.name like concat('%', #{name}, '%')
and goods.category_id = #{categoryId}
and goods.brand = #{brand}
order by goods.id desc

mapper.update:
update goods
name = #{name}, description = #{description}, price = #{price}, stock = #{stock}, img = #{img}, category_id = #{categoryId}, sales = #{sales}, store = #{store}, brand = #{brand}, content = #{content}, spec_list = #{specList},
where id = #{id}

update goods set
stock = stock - #{num},
sales = sales + #{num}
where id = #{id} and stock >= #{num}

update goods set
stock = stock + #{num},
sales = sales - #{num}
where id = #{id}
